class Solution {
public:
    int countDistinct(vector<int>& nums, int k, int p) {
        struct Node {
            unordered_map<int, Node*> children;
        };
        Node* root = new Node();
        int count = 0;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int divs = 0;
            Node* cur = root;
            for (int j = i; j < n; j++) {
                if (nums[j] % p == 0) divs++;
                if (divs > k) break;
                auto it = cur->children.find(nums[j]);
                if (it == cur->children.end()) {
                    Node* nxt = new Node();
                    cur->children[nums[j]] = nxt;
                    count++;
                    cur = nxt;
                } else {
                    cur = it->second;
                }
            }
        }
        return count;
    }
};
